import{z as i,x as d,o as e,c as o,q as t,j as n,D as a,d as A,s as C,S as B,b as s}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"签名方案的实践","description":"","frontmatter":{"title":"签名方案的实践","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ce-signature-practice.md","filePath":"cs/ce-signature-practice.md","lastUpdated":1791413859000}'),l={name:"cs/ce-signature-practice.md"};function D(c,E,h,m,p,F){const r=d("Mermaid");return e(),o("div",null,[E[2]||(E[2]=t('<h1 id="签名方案的实践" tabindex="-1">签名方案的实践 <a class="header-anchor" href="#签名方案的实践" aria-label="Permalink to &quot;签名方案的实践&quot;">​</a></h1><div class="epigraph"><p>签名方案的数学几十年没被推翻；被打穿的地方几乎都在随机数与输入校验上——$k$ 重复一次，私钥就从两行式里走出来。</p><footer>—— 据 RFC 8032；Bernstein 等, Ed25519；RFC 6979 整理</footer></div><p><a href="/cs/ce-aead-deep">上一课</a>把 AEAD 的合同与误用边界钉死，对称侧的保密与完整齐了。接下来是公钥侧的身份：主干<a href="/cs/mac-signature">MAC 与签名</a>分开了认证与不可否认，<a href="/cs/ecdsa-eddsa">ECDSA / EdDSA</a>给了两族方案，<a href="/cs/rsa-attacks">RSA 攻击面</a>解释了 RSA 为什么退居填充正确的形状。缺口是<strong>实践纪律</strong>：签什么（原始消息还是哈希）、nonce 怎么来、验证器要拒绝什么。方案本身选错的情况很少，纪律缺失时攻击不需要碰数学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ECDSA 与 EdDSA 同为椭圆曲线签名，合同却不同。ECDSA 要求每次签名一个新鲜的秘密 \\(k\\)：签名方程 \\(s = k^{-1}(H(m) + r\\,x) \\bmod n\\) 里，同一个 \\(k\\) 签两条消息，两式相减即解出私钥 \\(x\\)——2010 年 PS3 的签名密钥正是这样被算出来的。即使 \\(k\\) 只用一次但来自弱 CSPRNG，或带可利用的偏差（格攻击），同样致命。EdDSA 把 \\(k\\) 改成从私钥与消息哈希确定性派生；RFC 6979 给 ECDSA 同样的确定性补丁。缺口因此不是「哪条曲线安全」，而是三件实践事：\\(k\\) 的来源、签名的输入格式、验证器的严格性。<span class="marginnote">常见误区：以为「选了公认安全的曲线就安全了」。PS3 被破时曲线本身毫发无损，坏的是静态的 \\(k\\)；Android 钱包案里坏的是弱随机源。方案的安全性是数学、随机数、输入校验三件事的和，任何一件缺席，攻击都轮不到碰数学。</span></p><h3 id="验证器要拒绝什么" tabindex="-1">验证器要拒绝什么 <a class="header-anchor" href="#验证器要拒绝什么" aria-label="Permalink to &quot;验证器要拒绝什么&quot;">​</a></h3><p>签名验证是面向不可信输入的解析器。进代数之前必须逐项检查：公钥是群内点且不是无穷远点（退化点上曲线方程的恒等式可能自动成立，验证被白绕）；签名分量的数值落在 \\([1, n-1]\\)；编码严格解析（宽容的 DER 解析曾让签名可变形成交易重放）。Ed25519 已把点压缩、坐标范围、dom 域分离写进 RFC 8032，照文检查即可；自己拼装「先哈希再喂 ECDSA」时，这些检查要自己补齐。<span class="marginnote">「把验证器当解析器」可以类比海关验护照：先验证件的材质与格式，再查人证是否一致，两关都过才谈得上比对记录。跳过格式检查直接进「代数比对」，等于给假护照开后门——群外点攻击利用的正是这个窗口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实践规则四条。其一，\\(k\\) 一律确定性：Ed25519 用 RFC 8032 的派生式，ECDSA 用 RFC 6979——把在线随机数需求从签名里删掉，同时保留可注入额外熵的接口。其二，输入域分离：Ed25519 的 dom2 前缀把纯 Ed25519 与预哈希变体 Ed25519ph 分开，同一密钥混用两式会互签；应用层的消息类型也应进哈希前缀，防止「转账单」被改签成「确认单」。其三，签钥与协商钥分离——<a href="/cs/ecdh-x25519">ECDH 与 X25519</a>的 DH 密钥不该兼签身份，两处的泄露后果与暴露面不同。其四，输出规范化：ECDSA 取 low-s（把 \\(s\\) 折到 \\(n/2\\) 以下）消灭可变形；验证端拒绝 high-s。RSA 侧只接受 PSS（RFC 8017），PKCS#1 v1.5 签名只在遗留校验里出现。</p>',9)),(e(),n(B,null,{default:a(()=>[C(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIGN%5B%22%E8%A6%81%E7%AD%BE%E6%B6%88%E6%81%AF%20m%22%5D%20--%3E%20SCHEME%7B%22%E6%96%B9%E6%A1%88%3F%22%7D%0A%20%20SCHEME%20--%3E%7C%22Ed25519%22%7C%20DET1%5B%22k%20%E7%94%B1%E7%A7%81%E9%92%A5%E4%B8%8E%20H%20%E6%B4%BE%E7%94%9F%EF%BC%8CRFC%208032%22%5D%0A%20%20SCHEME%20--%3E%7C%22ECDSA%22%7C%20DET2%5B%22k%20%E7%A1%AE%E5%AE%9A%E6%80%A7%EF%BC%8CRFC%206979%22%5D%0A%20%20DET1%20--%3E%20CHECK%5B%22%E9%AA%8C%E8%AF%81%E5%99%A8%EF%BC%9A%E7%BE%A4%E5%86%85%E7%82%B9%E3%80%81%E5%88%86%E9%87%8F%E5%9C%A8%E7%95%8C%E5%86%85%E3%80%81%E4%B8%A5%E6%A0%BC%E7%BC%96%E7%A0%81%22%5D%0A%20%20DET2%20--%3E%20LOWS%5B%22%E8%BE%93%E5%87%BA%E5%8F%96%20low-s%EF%BC%8C%E6%8B%92%E7%BB%9D%E5%8F%98%E5%BD%A2%22%5D%0A%20%20CHECK%20--%3E%20OUT%5B%22%E7%AD%BE%E5%90%8D%E4%B8%8E%E5%85%AC%E9%92%A5%20%E2%86%92%20%E9%AA%8C%E8%AF%81%22%5D%0A%20%20LOWS%20--%3E%20OUT%0A%20%20RANDK%5B%22k%20%E5%A4%8D%E7%94%A8%E6%88%96%E5%BC%B1%E9%9A%8F%E6%9C%BA%22%5D%20--%3E%20LEAK%5B%22%E4%B8%A4%E7%AD%BE%E5%90%8D%E8%A7%A3%E5%87%BA%E7%A7%81%E9%92%A5%20x%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=s("h2",{id:"机制",tabindex:"-1"},[A("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=s("p",null,"确定性为什么够？被攻击的正是 \\(k\\) 的均匀性：\\(k = \\mathrm{PRF}(k_{\\mathrm{seed}}, H(m))\\) 的输出只要不可预测即可，不必真随机；Ed25519 干脆把消息哈希卷进派生，同一消息每次签名结果相同——重复投递由应用层序号去管，不是签名的职责。反过来，随机 \\(k\\) 的失败是集合式的：PS3 的静态 \\(k\\)、2013 年 Android 钱包弱随机导致的比特币密钥泄露、格攻击吃偏差，三条路汇到同一行代数。验证端同理：群外点让点加变成未定义行为，各库「容错」方向不同，签名等式在退化点上恒等成立，伪造免费。把验证器当解析器而不是当数学求值器，是这一课的机制核心。",-1)),(e(),n(B,null,{default:a(()=>[C(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20IN%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%E8%BE%93%E5%85%A5%EF%BC%9A%E7%AD%BE%E5%90%8D%E4%B8%8E%E5%85%AC%E9%92%A5%22%5D%20--%3E%20P1%7B%22%E5%85%AC%E9%92%A5%E6%98%AF%E7%BE%A4%E5%86%85%E7%82%B9%E4%B8%94%E9%9D%9E%E6%97%A0%E7%A9%B7%E8%BF%9C%EF%BC%9F%22%7D%0A%20%20P1%20--%3E%7C%22%E5%90%A6%22%7C%20REJ%5B%22%E6%8B%92%E7%BB%9D%EF%BC%8C%E4%B8%8D%E8%BF%9B%E4%BB%A3%E6%95%B0%22%5D%0A%20%20P1%20--%3E%7C%22%E6%98%AF%22%7C%20P2%7B%22%E7%AD%BE%E5%90%8D%E5%88%86%E9%87%8F%E8%90%BD%E5%9C%A8%201%20%E5%88%B0%20n-1%EF%BC%9F%22%7D%0A%20%20P2%20--%3E%7C%22%E5%90%A6%22%7C%20REJ%0A%20%20P2%20--%3E%7C%22%E6%98%AF%22%7C%20P3%7B%22%E7%BC%96%E7%A0%81%E4%B8%A5%E6%A0%BC%E8%A7%A3%E6%9E%90%E9%80%9A%E8%BF%87%EF%BC%9F%22%7D%0A%20%20P3%20--%3E%7C%22%E5%90%A6%22%7C%20REJ%0A%20%20P3%20--%3E%7C%22%E6%98%AF%22%7C%20ALG%5B%22%E4%BB%A3%E6%95%B0%E9%AA%8C%E8%AF%81%E7%AD%89%E5%BC%8F%22%5D%0A%20%20ALG%20--%3E%7C%22%E6%88%90%E7%AB%8B%22%7C%20OK%5B%22%E6%8E%A5%E5%8F%97%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">为什么 low-s 是「二选一收编」：ECDSA 的等式对 \\(s\\) 与 \\(n-s\\) 同时成立，同一份签名天然有两种合法编码，攻击者可拿另一种编码把已花的交易（或已投的消息）伪装成新的一条重放——2014 年比特币交易变形风波即属此类。约定只收 \\(s \\le n/2\\) 的一半，编码就只剩一种，变形空间归零。</span></p><p><span class="marginnote">两次签名共享 \\(k\\)：\\(s_1 - s_2 = k^{-1}(H(m_1) - H(m_2)) \\bmod n\\)，右端全部可算，先解出 \\(k\\)，代回任一式得私钥 \\(x\\)。2010 年 PS3 与 2013 年 Android 比特币钱包是同一行代数的两次执行。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管签名本身的纪律；公钥绑到名字（证书、信任链、吊销）是 <a href="/cs/tls-handshake">TLS 握手</a>与 PKI 层的事，<a href="/cs/mac-signature">MAC 与签名</a>已把「签名只证明某把私钥」钉为边界。哈希函数选择与碰撞界按<a href="/cs/birthday-attack">生日攻击</a>的口径取；长度扩展类问题按<a href="/cs/length-extension-hmac">长度扩展与 HMAC</a>的结论用标准结构规避。门限签名、聚合签名与后量子签名是「后量子概览」及更前沿课的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ECDSA 的 \\(k\\) 复用一次即解私钥；实践上一律确定性：Ed25519 派生式或 RFC 6979。</li><li>验证器是解析器：群内点、分量界、严格编码，逐项通过后才进代数。</li><li>签钥与 DH 钥分离；域分离（dom2、消息类型前缀）防跨语境互签。</li><li>ECDSA 取 low-s 消可变形；RSA 签名只接受 PSS。</li><li>出处：RFC 8032；RFC 6979；Bernstein 等, Ed25519；RFC 8017（PSS）。</li></ul>',6))])}const P=i(l,[["render",D]]);export{k as __pageData,P as default};
